import{_ as o,o as t,c as e,ag as i}from"./chunks/framework.B5ULsuav.js";const q=JSON.parse('{"title":"督脉","description":"","frontmatter":{},"headers":[],"relativePath":"50-概念资料/dict-督脉.md","filePath":"50-概念资料/dict-督脉.md","lastUpdated":1778155802000}'),l={name:"50-概念资料/dict-督脉.md"};function r(u,a,d,c,h,n){return t(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="督脉" tabindex="-1">督脉 <a class="header-anchor" href="#督脉" aria-label="Permalink to &quot;督脉&quot;">​</a></h1><blockquote><p>传统：丹道/中医</p></blockquote><h2 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to &quot;定义&quot;">​</a></h2><p>督脉是人体奇经八脉之一，位于身体后正中线，起于会阴，沿脊柱上行至头顶。督脉主&quot;阳&quot;，与全身阳经相连，被称为&quot;阳脉之海&quot;。</p><h2 id="了空居士原话" tabindex="-1">了空居士原话 <a class="header-anchor" href="#了空居士原话" aria-label="Permalink to &quot;了空居士原话&quot;">​</a></h2><blockquote><p>&quot;督脉在后，属阳。督脉通了，头顶就有真气上行的感觉。&quot;</p></blockquote><blockquote><p>&quot;气足的时候，背后会发热、发麻，像有东西沿着脊柱往上走。这些是正常现象，知道就好，不要去引导它。&quot;</p></blockquote><blockquote><p>&quot;但安神息，不运火而火自运——你只要心平气和地观照中丹田，气足了自己就会走。&quot;</p></blockquote><h2 id="了空居士的观点" tabindex="-1">了空居士的观点 <a class="header-anchor" href="#了空居士的观点" aria-label="Permalink to &quot;了空居士的观点&quot;">​</a></h2><p>了空居士对督脉的态度是&quot;不管它&quot;。运行督脉是自然发生的，不需要意念引导。如果有人教你&quot;意守尾闾&quot;&quot;引气上行&quot;，了空居士会告诉你这是有风险的。</p><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/liaokongjushi-wisdom/50-概念资料/dict-任脉">任脉</a> — 与督脉对应</li><li><a href="/liaokongjushi-wisdom/50-概念资料/dict-小周天">小周天</a> — 任督循环</li><li><a href="/liaokongjushi-wisdom/50-概念资料/dict-丹田">丹田</a> — 命门在督脉上</li></ul><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/liaokongjushi-wisdom/10-核心模型/model-性命双修">性命双修</a></li></ul>',14)])])}const p=o(l,[["render",r]]);export{q as __pageData,p as default};
